/**
 * Turning a downloaded build into a Polaris build (`format.ts`), offline, before
 * it ships. Never run on a server.
 *
 * Reads the Sponge schematic (`.schem`, versions 2 and 3), the format current
 * world editors save, and the older MCEdit `.schematic`, which stores a numeric
 * block id and data value per cell from before 1.13. Those are turned into
 * today's block states with `legacy-blocks.json` (generated by
 * `scripts/legacy-blocks.mjs`, which names its source). A data value the table
 * does not know becomes its id's base state, and an id it does not know becomes
 * air; both are counted in the conversion's report, never dropped unnoticed.
 *
 * What a build carries besides blocks - chest contents, sign text, entities - is
 * left out, and so are water and lava, which would flow out of the build's box.
 */

import { gunzipSync } from "node:zlib";
import legacyBlocks from "./legacy-blocks.json";
import { AIR, encodeCells, polarisBuildSchema, SIDE_MAX, type PolarisBuild } from "./format";

type Tag =
    | number
    | bigint
    | string
    | Tag[]
    | Int8Array
    | Int32Array
    | BigInt64Array
    | { [name: string]: Tag };

/** A gzipped (or plain) NBT file's root compound. */
export function readNbt(bytes: Uint8Array): Record<string, Tag> {
    const data = bytes[0] === 0x1f && bytes[1] === 0x8b ? gunzipSync(bytes) : Buffer.from(bytes);
    const view = new DataView(data.buffer, data.byteOffset, data.byteLength);
    let at = 0;
    const text = () => {
        const length = view.getUint16(at);
        at += 2;
        const value = data.subarray(at, at + length).toString("utf8");
        at += length;
        return value;
    };
    const count = () => {
        const length = view.getInt32(at);
        at += 4;
        if (length < 0 || length > data.byteLength) throw new Error("NBT length out of range");
        return length;
    };
    const payload = (type: number): Tag => {
        switch (type) {
            case 1:
                return view.getInt8(at++);
            case 2:
                at += 2;
                return view.getInt16(at - 2);
            case 3:
                at += 4;
                return view.getInt32(at - 4);
            case 4:
                at += 8;
                return view.getBigInt64(at - 8);
            case 5:
                at += 4;
                return view.getFloat32(at - 4);
            case 6:
                at += 8;
                return view.getFloat64(at - 8);
            case 7: {
                const length = count();
                const value = new Int8Array(data.subarray(at, at + length));
                at += length;
                return value;
            }
            case 8:
                return text();
            case 9: {
                const inner = view.getInt8(at++);
                const length = count();
                return Array.from({ length }, () => payload(inner));
            }
            case 10: {
                const value: Record<string, Tag> = {};
                for (let inner = view.getInt8(at++); inner !== 0; inner = view.getInt8(at++))
                    value[text()] = payload(inner);
                return value;
            }
            case 11: {
                const length = count();
                return Int32Array.from({ length }, () => {
                    at += 4;
                    return view.getInt32(at - 4);
                });
            }
            case 12: {
                const length = count();
                return BigInt64Array.from({ length }, () => {
                    at += 8;
                    return view.getBigInt64(at - 8);
                });
            }
            default:
                throw new Error(`unknown NBT tag ${type}`);
        }
    };
    if (view.getInt8(at++) !== 10) throw new Error("not an NBT compound");
    text();
    return payload(10) as Record<string, Tag>;
}

/** Sponge's block data: one unsigned varint per cell. */
function varints(bytes: Int8Array, cells: number): number[] {
    const values: number[] = [];
    let value = 0;
    let shift = 0;
    for (const byte of bytes) {
        value |= (byte & 0x7f) << shift;
        if ((byte & 0x80) === 0) {
            values.push(value);
            value = 0;
            shift = 0;
        } else if ((shift += 7) > 28) throw new Error("block data varint too long");
    }
    if (values.length !== cells)
        throw new Error(`block data holds ${values.length} cells, not ${cells}`);
    return values;
}

const FLUIDS = new Set(["minecraft:water", "minecraft:lava", "minecraft:bubble_column"]);
const SKIPPED = new Set([
    AIR,
    "minecraft:cave_air",
    "minecraft:void_air",
    "minecraft:structure_void",
    ...FLUIDS
]);

/** A block state with its water taken out: water would flow out of the build's box. */
function dry(state: string): string {
    const open = state.indexOf("[");
    if (open === -1) return state;
    const kept = state
        .slice(open + 1, -1)
        .split(",")
        .filter((one) => one !== "waterlogged=true");
    return kept.length === 0 ? state.slice(0, open) : `${state.slice(0, open)}[${kept.join(",")}]`;
}

/** What a conversion had to stand in for, as `id:data` -> how many cells. */
export interface ConversionReport {
    /** A legacy data value the table does not know: placed as its id's base state. */
    substituted: Record<string, number>;
    /** A legacy id the table does not know at all: left as air. */
    unknown: Record<string, number>;
}

/** Legacy id -> its states by data value, without the `minecraft:` namespace. */
const LEGACY: Record<string, (string | null)[]> = legacyBlocks;

type Outcome = { state: string; missed?: keyof ConversionReport };

/** A pre-1.13 id and data value as today's block state. */
function legacyState(id: number, data: number): Outcome {
    const states = LEGACY[id];
    const exact = states?.[data];
    if (exact) return { state: `minecraft:${exact}` };
    const base = states?.[0] ?? states?.find(Boolean);
    return base
        ? { state: `minecraft:${base}`, missed: "substituted" }
        : { state: AIR, missed: "unknown" };
}

/** An MCEdit schematic's cells as states, and what had to be stood in for. */
function legacyCells(schematic: Record<string, Tag>, cells: number) {
    if (schematic.Materials !== undefined && schematic.Materials !== "Alpha")
        throw new Error(`an MCEdit .schematic of ${String(schematic.Materials)} blocks`);
    const ids = schematic.Blocks as Int8Array;
    const values = schematic.Data;
    const add = schematic.AddBlocks;
    if (!(values instanceof Int8Array) || ids.length !== cells || values.length !== cells)
        throw new Error(`block data does not hold ${cells} cells`);
    const names: string[] = [];
    const outcomes: Outcome[] = [];
    const seen = new Map<number, number>();
    const report: ConversionReport = { substituted: {}, unknown: {} };
    const indexes = Array.from({ length: cells }, (_, at) => {
        // AddBlocks holds an id's high four bits, two cells to a byte, the even
        // cell in the low nibble (as WorldEdit reads it).
        const high =
            add instanceof Int8Array && at >> 1 < add.length
                ? at % 2 === 0
                    ? (add[at >> 1]! & 0x0f) << 8
                    : (add[at >> 1]! & 0xf0) << 4
                : 0;
        const id = high | (ids[at]! & 0xff);
        const data = values[at]! & 0x0f;
        let index = seen.get(id * 16 + data);
        if (index === undefined) {
            const outcome = legacyState(id, data);
            index = names.push(outcome.state) - 1;
            outcomes.push(outcome);
            seen.set(id * 16 + data, index);
        }
        const missed = outcomes[index]!.missed;
        if (missed) report[missed][`${id}:${data}`] = (report[missed][`${id}:${data}`] ?? 0) + 1;
        return index;
    });
    return { names, indexes, report };
}

/** A schematic's bytes - Sponge or MCEdit - as a Polaris build, and its report. */
export function convertSchematic(
    bytes: Uint8Array,
    id: string,
    season: PolarisBuild["season"]
): { build: PolarisBuild; report: ConversionReport } {
    const root = readNbt(bytes);
    const schematic = (typeof root.Schematic === "object" ? root.Schematic : root) as Record<
        string,
        Tag
    >;
    const size = {
        x: Number(schematic.Width),
        y: Number(schematic.Height),
        z: Number(schematic.Length)
    };
    if (Object.values(size).some((side) => !(side >= 1 && side <= SIDE_MAX)))
        throw new Error(`too large to place near spawn: ${size.x}x${size.y}x${size.z}`);
    const total = size.x * size.y * size.z;
    // Version 2 keeps the palette at the top, version 3 under `Blocks`; the MCEdit
    // format has `Blocks` too, as a plain array of numeric ids and no palette.
    const holder = schematic.Palette !== undefined ? schematic : schematic.Blocks;
    let names: string[];
    let indexes: number[];
    let report: ConversionReport = { substituted: {}, unknown: {} };
    if (holder instanceof Int8Array) ({ names, indexes, report } = legacyCells(schematic, total));
    else if (holder && typeof holder === "object" && "Palette" in holder) {
        const blocks = holder as Record<string, Tag>;
        const source = blocks.Palette as Record<string, Tag>;
        names = [];
        for (const [name, index] of Object.entries(source)) names[Number(index)] = name;
        indexes = varints((blocks.Data ?? blocks.BlockData) as Int8Array, total);
    } else throw new Error("neither a Sponge nor an MCEdit schematic");
    // Air first, every other kept state after it; fluids and voids become air.
    const palette = [AIR];
    const remap = names.map((name) => {
        if (SKIPPED.has(name.replace(/\[.*$/, ""))) return 0;
        const state = dry(name);
        const found = palette.indexOf(state);
        return found === -1 ? palette.push(state) - 1 : found;
    });
    const cells = indexes.map((index) => remap[index] ?? 0);
    const build = polarisBuildSchema.parse({
        format: "polaris-build",
        version: 1,
        id,
        season,
        size,
        palette,
        blocks: encodeCells(cells)
    });
    return { build, report };
}

/** A schematic's bytes as a Polaris build, without the report. */
export function convertSponge(
    bytes: Uint8Array,
    id: string,
    season: PolarisBuild["season"]
): PolarisBuild {
    return convertSchematic(bytes, id, season).build;
}
